// 27-tap FIR, TRANSPOSED direct form: one multiply + one add per stage, so the
// register-to-register critical path as a function of tap -> short path. Same
// function as the direct form (see the TRANSPOSED form comment for details).
// Same transfer function as the direct form (the TRANSPOSED form).
module firr27_v3 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg [23:0] a0, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, a13, a14, a15, a16, a17, a18, a19, a20, a21, a22, a23, a24, a25, a26;
    always @(posedge clk) begin
        if (!rst_n) begin
            a0 <= 24'd0; a1 <= 24'd0; a2 <= 24'd0; a3 <= 24'd0; a4 <= 24'd0; a5 <= 24'd0; a6 <= 24'd0; a7 <= 24'd0; a8 <= 24'd0; a9 <= 24'd0; a10 <= 24'd0; a11 <= 24'd0; a12 <= 24'd0; a13 <= 24'd0; a14 <= 24'd0; a15 <= 24'd0; a16 <= 24'd0; a17 <= 24'd0; a18 <= 24'd0; a19 <= 24'd0; a20 <= 24'd0; a21 <= 24'd0; a22 <= 24'd0; a23 <= 24'd0; a24 <= 24'd0; a25 <= 24'd0; a26 <= 24'd0; y <= 16'd0;
        end else begin
            a0 <= 8'd2 * x + 5'd26;
            a1 <= 8'd4 * x + 5'd24;
            a2 <= 8'd6 * x + 5'd22;
            a3 <= 8'd8 * x + 5'd20;
            a4 <= 8'd10 * x + 5'd18;
            a5 <= 8'd12 * x + 5'd16;
            a6 <= 8'd14 * x + 5'd14;
            a7 <= 8'd16 * x + 5'd12;
            a8 <= 8'd18 * x + 5'd10;
            a9 <= 8'd20 * x + 5'd8;
            a10 <= 8'd22 * x + 5'd6;
            a11 <= 8'd24 * x + 5'd4;
            a12 <= 8'd26 * x + 5'd2;
            a13 <= 8'd28 * x;
            a14 <= 8'd30 * x;
            a15 <= 8'd32 * x;
            a16 <= 8'd34 * x;
            a17 <= 8'd36 * x;
            a18 <= 8'd38 * x;
            a19 <= 8'd40 * x;
            a20 <= 8'd42 * x;
            a21 <= 8'd44 * x;
            a22 <= 8'd46 * x;
            a23 <= 8'd48 * x;
            a24 <= 8'd50 * x;
            a25 <= 8'd52 * x;
            a26 <= 8'd54 * x;
            y <= a0 + a1 + a2 + a3 + a4 + a5 + a6 + a7 + a8 + a9 + a10 + a11 + a12 + a13 + a14 + a15 + a16 + a17 + a18 + a19 + a20 + a21 + a22 + a23 + a24 + a25 + a26;
        end
    end
endmodule
